/* Restricted Arduino teaching interpreter. No eval, remote compiler, or CPU emulation. */
function exprTokens(source){const result=[];let i=0;while(i<source.length){if(/\s/.test(source[i])){i++;continue}const match=source.slice(i).match(/^(?:"(?:\\.|[^"\\])*"|\d+(?:\.\d+)?|[A-Za-z_]\w*|==|!=|<=|>=|&&|\|\||[()+\-*\/%!,<>])/);if(!match)throw Error('תו לא נתמך בביטוי: '+source.slice(i, i+15));result.push(match[0]);i+=match[0].length}return result}
function evaluateExpression(source){const tokens=exprTokens(source);let i=0,depth=0;const precedence={'||':1,'&&':2,'==':3,'!=':3,'<':4,'>':4,'<=':4,'>=':4,'+':5,'-':5,'*':6,'/':6,'%':6};function primary(){if(++depth>40)throw Error('ביטוי עמוק מדי');let value;const t=tokens[i++];if(!t)throw Error('חסר ערך בביטוי');if(t==='('){value=binary(0);if(tokens[i++]!==')')throw Error('חסר סוגר');}else if(t==='!'||t==='-'||t==='+'){const n=primary();value=t==='!'?!n:t==='-'?-Number(n):Number(n)}else if(t[0]==='"')value=JSON.parse(t);else if(/^\d/.test(t))value=Number(t);else if(/^[A-Za-z_]\w*$/.test(t)){if(tokens[i]==='('){i++;const args=[];if(tokens[i]!==')')do{args.push(binary(0));if(tokens[i]!==',')break;i++}while(true);if(tokens[i++]!==')')throw Error('חסר סוגר לפונקציה '+t);const exact=n=>{if(args.length!==n)throw Error('מספר ארגומנטים שגוי: '+t)};if(t==='analogRead'||t==='digitalRead'){exact(1);value=readPin(args[0],t==='analogRead')}else if(t==='millis'){exact(0);value=Date.now()-codeStart}else if(t==='map'){exact(5);if(args[2]===args[1])throw Error('טווח map ריק');value=Math.trunc((args[0]-args[1])*(args[4]-args[3])/(args[2]-args[1])+args[3])}else if(t==='constrain'){exact(3);value=Math.max(args[1],Math.min(args[2],args[0]))}else throw Error('פונקציה לא נתמכת: '+t)}else if(Object.hasOwn(vars,t))value=vars[t];else if(/^A\d+$/.test(t))value=t;else if(['HIGH','OUTPUT','true'].includes(t))value=1;else if(['LOW','INPUT','false'].includes(t))value=0;else if(t==='INPUT_PULLUP')value=2;else throw Error('משתנה לא מוגדר: '+t)}else throw Error('ביטוי לא תקין: '+t);depth--;return value}function binary(min){let left=primary();while(i<tokens.length&&precedence[tokens[i]]>=min){const op=tokens[i++],right=binary(precedence[op]+1);switch(op){case'+':left=left+right;break;case'-':left=left-right;break;case'*':left=left*right;break;case'/':if(+right===0)throw Error('חלוקה באפס');left=left/right;break;case'%':if(+right===0)throw Error('חלוקה באפס');left=left%right;break;case'==':left=left===right;break;case'!=':left=left!==right;break;case'<':left=left<right;break;case'>':left=left>right;break;case'<=':left=left<=right;break;case'>=':left=left>=right;break;case'&&':left=!!left&&!!right;break;case'||':left=!!left||!!right;break}}return left}const result=binary(0);if(i!==tokens.length)throw Error('שארית לא תקינה בביטוי');if(typeof result==='number'&&!Number.isFinite(result))throw Error('תוצאה מספרית לא תקינה');return result}
function splitArguments(source){const args=[];let depth=0,start=0,quote=false,escape=false;for(let i=0;i<source.length;i++){const c=source[i];if(escape){escape=false;continue}if(c==='\\'&&quote){escape=true;continue}if(c==='"'){quote=!quote;continue}if(quote)continue;if(c==='(')depth++;if(c===')')depth--;if(c===','&&depth===0){args.push(source.slice(start,i).trim());start=i+1}}if(source.trim())args.push(source.slice(start).trim());return args}
function compileTeachingCode(code){if(code.length>100000)throw Error('הסקיצה גדולה מדי');const cleaned=code.replace(/"(?:\\.|[^"\\])*"|\/\*[\s\S]*?\*\/|\/\/[^\n]*/g,s=>s.startsWith('"')?s:' ');let at=0;function skip(){while(/\s/.test(cleaned[at]||'')&&at<cleaned.length)at++}// Brace/parenthesis readers keep strings intact.
function readBalanced(open,close){skip();if(cleaned[at]!==open)throw Error('ציפיתי ל־'+open);let depth=1,start=++at,quote=false;while(at<cleaned.length){const c=cleaned[at++];if(c==='\\'&&quote){at++;continue}if(c==='"'){quote=!quote;continue}if(quote)continue;if(c===open)depth++;if(c===close){depth--;if(depth===0)return cleaned.slice(start,at-1)}}throw Error('חסר '+close)}
const functions={},globals=[];while(at<cleaned.length){skip();if(at>=cleaned.length)break;const fn=cleaned.slice(at).match(/^void\s+(setup|loop)\s*\(\s*\)/);if(fn){at+=fn[0].length;if(functions[fn[1]]!==undefined)throw Error('פונקציה כפולה: '+fn[1]);functions[fn[1]]=readBalanced('{','}')}else{let start=at,quote=false;while(at<cleaned.length){const c=cleaned[at++];if(c==='"')quote=!quote;if(c===';'&&!quote)break;if(c==='{'&&!quote)throw Error('נתמכות setup ו־loop בלבד')}globals.push(cleaned.slice(start,at))}}
if(functions.setup===undefined||functions.loop===undefined)throw Error('יש להגדיר void setup() ו־void loop()');let parseDepth=0;function statements(source,allowIf=true){if(++parseDepth>30)throw Error('יותר מדי בלוקים מקוננים');let pos=0;const out=[];const space=()=>{while(pos<source.length&&/\s/.test(source[pos]))pos++};function region(open,close){space();if(source[pos++]!==open)throw Error('חסר '+open);const begin=pos;let level=1,quote=false;while(pos<source.length){const c=source[pos++];if(c==='\\'&&quote){pos++;continue}if(c==='"'){quote=!quote;continue}if(quote)continue;if(c===open)level++;if(c===close&&--level===0)return source.slice(begin,pos-1)}throw Error('חסר '+close)}while(pos<source.length){space();if(pos>=source.length)break;if(/^if\b/.test(source.slice(pos))){if(!allowIf)throw Error('תנאים נתמכים בתוך loop בלבד');pos+=2;const cond=region('(',')'),yes=statements(region('{','}'));space();let no=[];if(/^else\b/.test(source.slice(pos))){pos+=4;no=statements(region('{','}'))}out.push({kind:'if',cond,yes,no});continue}const begin=pos;let quote=false,par=0;while(pos<source.length){const c=source[pos++];if(c==='\\'&&quote){pos++;continue}if(c==='"')quote=!quote;if(!quote){if(c==='(')par++;if(c===')')par--;if(c===';'&&par===0)break;if(c==='{'||c==='}')throw Error('בלוק לא נתמך')}}if(source[pos-1]!==';')throw Error('חסר ; בסוף פקודה');const text=source.slice(begin,pos-1).trim();if(!text)continue;const variable=text.match(/^(?:(?:const\s+)?(?:int|float|long|bool|unsigned\s+long)\s+)?([A-Za-z_]\w*)\s*=\s*([^=].*)$/s);if(variable){out.push({kind:'var',name:variable[1],expr:variable[2]});continue}const m=text.match(/^(pinMode|digitalWrite|analogWrite|delay|Serial\.begin|Serial\.print|Serial\.println)\s*\(([\s\S]*)\)$/);if(!m)throw Error('פקודה לא נתמכת: '+text.slice(0,70));const args=splitArguments(m[2]),count=['pinMode','digitalWrite','analogWrite'].includes(m[1])?2:1;if(args.length!==count)throw Error('מספר ארגומנטים שגוי: '+m[1]);out.push({kind:'call',fn:m[1],args})}parseDepth--;return out}function lower(list,out=[]){for(const s of list){if(s.kind!=='if'){out.push(s);continue}const check={kind:'branch',cond:s.cond,target:0};out.push(check);lower(s.yes,out);const jump={kind:'jump',target:0};out.push(jump);check.target=out.length;lower(s.no,out);jump.target=out.length}return out}const setup=statements(globals.join('\n')+'\n'+functions.setup,false);return{setup,loop:lower(statements(functions.loop))}}
const legacyExecute=execute;tokenValue=evaluateExpression;compileCode=compileTeachingCode;execute=function(stmt){if(stmt.kind==='branch'){if(!evaluateExpression(stmt.cond))pc=stmt.target-1;return 0}if(stmt.kind==='jump'){pc=stmt.target-1;return 0}return legacyExecute(stmt)};
const teachingOpenCode=openCode;openCode=function(force){teachingOpenCode(force);if(board()&&!catalog.find(c=>c.type===board().type).python)document.querySelector('.codewarning').textContent='מפרש לימודי: setup/loop, משתנים, חישובים, if/else עם סוגריים מסולסלים, GPIO, analogRead, map, constrain ו־Serial. ללא ספריות, לולאות for/while או אמולציית מעבד.'};
